const SCHEMA = [
  `CREATE TABLE IF NOT EXISTS docs (path TEXT PRIMARY KEY, coll TEXT NOT NULL, data TEXT NOT NULL)`,
  `CREATE INDEX IF NOT EXISTS docs_coll ON docs(coll)`,
  `CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, hash TEXT NOT NULL, salt TEXT NOT NULL, created INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, uid TEXT NOT NULL, created INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY, v TEXT NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS push_subs (endpoint TEXT PRIMARY KEY, uid TEXT NOT NULL, p256dh TEXT NOT NULL, auth TEXT NOT NULL, created INTEGER NOT NULL)`,
  `CREATE INDEX IF NOT EXISTS push_uid ON push_subs(uid)`,
  `CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY, uid TEXT NOT NULL, type TEXT NOT NULL, size INTEGER NOT NULL, parts INTEGER NOT NULL, done INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL)`,
  `CREATE TABLE IF NOT EXISTS media_parts (id TEXT NOT NULL, part INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(id, part))`,
];
let schemaReady = false;
async function ensureSchema(env){ if(schemaReady) return; await env.DB.batch(SCHEMA.map(q=>env.DB.prepare(q))); schemaReady = true; }

const json = (obj, status=200) => new Response(JSON.stringify(obj), {status, headers:{'content-type':'application/json','cache-control':'no-store'}});
class HttpError extends Error { constructor(status, code, msg){ super(msg); this.status=status; this.code=code; this.msg=msg; } }
const fail = (status, code, msg) => { throw new HttpError(status, code, msg); };

// ---------- auth ----------
const hex = buf => [...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('');
const randHex = n => hex(crypto.getRandomValues(new Uint8Array(n)));
const randId = n => { const a='abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789'; return [...crypto.getRandomValues(new Uint8Array(n))].map(b=>a[b%a.length]).join(''); };
async function hashPw(pw, saltHex){
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(pw), 'PBKDF2', false, ['deriveBits']);
  const salt = new Uint8Array(saltHex.match(/../g).map(h=>parseInt(h,16)));
  return hex(await crypto.subtle.deriveBits({name:'PBKDF2', hash:'SHA-256', salt, iterations:20000}, key, 256));
}
function sameStr(a,b){ if(a.length!==b.length) return false; let r=0; for(let i=0;i<a.length;i++) r|=a.charCodeAt(i)^b.charCodeAt(i); return r===0; }
async function newSession(env, uid){ const token = randHex(32); await env.DB.prepare('INSERT INTO sessions(token,uid,created) VALUES(?,?,?)').bind(token, uid, Date.now()).run(); return token; }
async function userFrom(req, env){
  const m = (req.headers.get('authorization')||'').match(/^Bearer ([a-f0-9]{64})$/);
  if(!m) fail(401,'unauthorized','Please log in again.');
  const row = await env.DB.prepare('SELECT uid FROM sessions WHERE token=?').bind(m[1]).first();
  if(!row) fail(401,'unauthorized','Please log in again.');
  return row.uid;
}

// ---------- documents ----------
const SEG = /^[A-Za-z0-9_~.\-]{1,200}$/;
function checkPath(path, wantDoc){
  if(typeof path!=='string') fail(400,'invalid','Bad path.');
  const s = path.split('/'); if(s.length>8 || !s.every(x=>SEG.test(x) && x!=='.' && x!=='..')) fail(400,'invalid','Bad path.');
  if(wantDoc !== (s.length%2===0)) fail(400,'invalid','Bad path.');
  return s;
}
const collOf = path => path.split('/').slice(0,-1).join('/');
const rootOf = path => path.split('/')[0];
async function getDoc(env, path){ const r = await env.DB.prepare('SELECT data FROM docs WHERE path=?').bind(path).first(); return r ? JSON.parse(r.data) : null; }
const bump = (env, path) => env.DB.prepare('INSERT INTO meta(k,v) VALUES(?,1) ON CONFLICT(k) DO UPDATE SET v=v+1').bind(rootOf(path));
async function putDoc(env, path, data){
  const body = JSON.stringify(data); if(body.length > 1500000) fail(413,'too-big','That’s too large to save.');
  await env.DB.batch([env.DB.prepare('INSERT INTO docs(path,coll,data) VALUES(?,?,?) ON CONFLICT(path) DO UPDATE SET data=excluded.data').bind(path, collOf(path), body), bump(env, path)]);
}
async function delDoc(env, path){ await env.DB.batch([env.DB.prepare('DELETE FROM docs WHERE path=?').bind(path), bump(env, path)]); }
const isObj = v => v && typeof v==='object' && !Array.isArray(v);
function deepMerge(a, b){ const o = {...(isObj(a)?a:{})}; for(const k in b){ const v=b[k]; o[k] = isObj(v) && Object.keys(v).length ? deepMerge(o[k], v) : v; } return o; }
const FIELD = /^[A-Za-z0-9_]{1,40}$/;
async function runQuery(env, path, where, order, limit){
  let sql = 'SELECT path, data FROM docs WHERE coll=?'; const binds = [path];
  for(const w of (where||[])){ const [f,op,v] = w; if(!FIELD.test(f)) fail(400,'invalid','Bad query.');
    if(op==='==') { sql += ` AND json_extract(data,'$.${f}')=?`; binds.push(v); }
    else if(op==='array-contains'){ sql += ` AND EXISTS (SELECT 1 FROM json_each(docs.data,'$.${f}') WHERE json_each.value=?)`; binds.push(v); }
    else fail(400,'invalid','Bad query.'); }
  if(order){ const [f,d] = order; if(!FIELD.test(f)) fail(400,'invalid','Bad query.'); sql += ` ORDER BY json_extract(data,'$.${f}') ${d==='desc'?'DESC':'ASC'}`; }
  sql += ` LIMIT ${Math.max(1, Math.min(1000, +limit || 1000))}`;
  const r = await env.DB.prepare(sql).bind(...binds).all();
  return r.results.map(x => [x.path.split('/').pop(), JSON.parse(x.data)]);
}

// ---------- access rules ----------
async function isCommMember(env, id, me){ const c = await getDoc(env, 'comms/'+id); return !!c && (c.members||[]).includes(me); }
function sameExcept(a, b, keys){ const ks = new Set([...Object.keys(a||{}), ...Object.keys(b||{})]); for(const k of ks){ if(keys.includes(k)) continue; if(JSON.stringify(a?.[k])!==JSON.stringify(b?.[k])) return false; } return true; }
function onlyMine(a, b, me){ a=a||{}; b=b||{}; const ks = new Set([...Object.keys(a), ...Object.keys(b)]); for(const k of ks){ if(k===me) continue; if(JSON.stringify(a[k])!==JSON.stringify(b[k])) return false; } return true; }
async function isMember(env, chatId, me){ const c = await getDoc(env, 'chats/'+chatId); return !!c && (c.members||[]).includes(me); }
async function canRead(env, me, path, q){
  const s = path.split('/');
  if(q){
    if(['profiles','posts','stories','presence','comms','threads'].includes(path)) return true;
    if(s.length===3 && s[0]==='threads' && s[2]==='replies') return true;
    if(s.length===3 && s[0]==='comms' && s[2]==='chat') return isCommMember(env, s[1], me);
    if(path==='friends' || path==='chats') return (q.where||[]).some(([f,op,v]) => f==='members' && op==='array-contains' && v===me);
    if(s.length===3 && s[0]==='posts' && s[2]==='comments') return true;
    if(s.length===3 && s[0]==='chats' && s[2]==='msgs') return isMember(env, s[1], me);
    if(s.length===3 && s[0]==='notifs' && s[2]==='items') return s[1]===me;
    return false;
  }
  switch(s[0]){
    case 'profiles': case 'usernames': case 'codes': case 'stories': case 'images': case 'presence': return s.length===2;
    case 'posts': return s.length===2 || (s.length===4 && s[2]==='comments');
    case 'friends': return s.length===2 && s[1].split('~').includes(me);
    case 'chats': if(s.length===2){ const c = await getDoc(env, path); return !c || (c.members||[]).includes(me); } return s.length===4 && s[2]==='msgs' && isMember(env, s[1], me);
    case 'notifs': return s.length===4 && s[1]===me;
    case 'comms': return s.length===2 || (s.length===4 && s[2]==='chat' && isCommMember(env, s[1], me));
    case 'threads': return s.length===2 || (s.length===4 && s[2]==='replies');
  }
  return false;
}
async function canWrite(env, me, op, path, old, neu){
  const s = path.split('/'); const del = op==='delete';
  switch(s[0]){
    case 'profiles': case 'presence': return s.length===2 && s[1]===me;
    case 'usernames': case 'codes': if(s.length!==2) return false; if(old && old.uid!==me) return false; return del || neu.uid===me;
    case 'friends': { if(s.length!==2) return false; const ids = s[1].split('~'); if(ids.length!==2 || !ids.includes(me)) return false;
      if(del) return true;
      if(!old) return neu.requestedBy===me && neu.status==='pending' && JSON.stringify([...(neu.members||[])].sort())===JSON.stringify([...ids].sort());
      return JSON.stringify(neu.members)===JSON.stringify(old.members) && neu.requestedBy===old.requestedBy && (neu.status==='pending' || old.requestedBy!==me); }
    case 'chats':
      if(s.length===2){ if(del) return false; if(!old) return Array.isArray(neu.members) && neu.members.includes(me) && neu.members.length<=64;
        if(!(old.members||[]).includes(me) || !Array.isArray(neu.members) || neu.members.length>64) return false;
        if(old.type!=='group') return JSON.stringify(neu.members)===JSON.stringify(old.members) && neu.type===old.type;
        if(neu.type!=='group' || neu.createdBy!==old.createdBy) return false;
        const removed = old.members.filter(m=>!neu.members.includes(m));
        return removed.every(m=>m===me) || old.createdBy===me; }
      if(s.length===4 && s[2]==='msgs'){ if(!(await isMember(env, s[1], me))) return false; if(del) return old?.by===me;
        if(!old){ if(neu.by!==me) return false; const ch = await getDoc(env, 'chats/'+s[1]);
          if(ch?.type==='dm'){ const f = await getDoc(env, 'friends/'+[...ch.members].sort().join('~')); if(f?.status!=='accepted') return false; } return true; }
        return neu.by===old.by; }
      return false;
    case 'posts': case 'stories':
      if(s.length===2){ if(del) return old?.by===me; if(!old) return neu.by===me; return neu.by===old.by; }
      if(s[0]==='posts' && s.length===4 && s[2]==='comments'){ if(del){ if(old?.by===me) return true; const p = await getDoc(env, 'posts/'+s[1]); return p?.by===me; } return !old && neu.by===me; }
      return false;
    case 'images': if(s.length!==2) return false; if(del) return old?.by===me; return !old && neu.by===me;
    case 'comms': {
      if(s.length===2){
        if(del) return old?.by===me;
        const nameOK = typeof neu.name==='string' && neu.name.trim().length>=2 && neu.name.length<=40 && String(neu.desc||'').length<=300 && Array.isArray(neu.members);
        if(!old) return nameOK && neu.by===me && neu.members.length===1 && neu.members[0]===me;
        if(!nameOK || neu.by!==old.by) return false;
        if(old.by===me) return neu.members.includes(me);
        if(!sameExcept(old, neu, ['members'])) return false;
        const a = new Set(old.members||[]), b = new Set(neu.members); if(b.size!==neu.members.length) return false;
        return [...a].filter(x=>!b.has(x)).concat([...b].filter(x=>!a.has(x))).every(x=>x===me);
      }
      if(s.length===4 && s[2]==='chat'){ const c = await getDoc(env, 'comms/'+s[1]); if(!c) return false;
        if(del) return old?.by===me || c.by===me; if(old) return false;
        return neu.by===me && (c.members||[]).includes(me) && typeof neu.text==='string' && !!neu.text.trim() && neu.text.length<=2000; }
      return false; }
    case 'threads': {
      if(s.length===2){
        if(del){ if(old?.by===me) return true; const c = await getDoc(env, 'comms/'+old?.comm); return c?.by===me; }
        if(!old){ if(neu.by!==me || typeof neu.title!=='string' || !neu.title.trim() || neu.title.length>200 || String(neu.body||'').length>4000) return false;
          const c = await getDoc(env, 'comms/'+neu.comm); return !!c && (c.members||[]).includes(me); }
        if(neu.by!==old.by || neu.comm!==old.comm) return false;
        if(old.by===me) return true;
        return sameExcept(old, neu, ['votes','ncomments','lastTs']) && onlyMine(old.votes, neu.votes, me);
      }
      if(s.length===4 && s[2]==='replies'){
        const t = await getDoc(env, 'threads/'+s[1]); if(!t) return false;
        if(del){ if(old?.by===me) return true; const c = await getDoc(env, 'comms/'+t.comm); return c?.by===me; }
        if(!old){ if(neu.by!==me || typeof neu.text!=='string' || !neu.text.trim() || neu.text.length>4000) return false;
          const c = await getDoc(env, 'comms/'+t.comm); return !!c && (c.members||[]).includes(me); }
        if(neu.by!==old.by) return false; if(old.by===me) return true;
        return sameExcept(old, neu, ['likes']) && onlyMine(old.likes, neu.likes, me);
      }
      return false; }
    case 'notifs': if(s.length!==4 || s[2]!=='items') return false; if(del) return s[1]===me || old?.from===me; return neu.from===me;
  }
  return false;
}
const denied = () => fail(403,'permission-denied','You don’t have permission to do that.');

// ---------- API ----------
async function api(req, env, route, ctx){
  const body = await req.json().catch(()=>({}));
  if(route==='/api/signup'){
    const email = String(body.email||'').trim().toLowerCase(), pw = String(body.password||'');
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) fail(400,'invalid','That email address doesn’t look right.');
    if(pw.length < 8) fail(400,'invalid','Use a password with at least 8 characters.');
    if(await env.DB.prepare('SELECT 1 FROM users WHERE email=?').bind(email).first()) fail(409,'exists','An account already uses that email. Log in instead.');
    const id = 'u' + randId(20), salt = randHex(16);
    await env.DB.prepare('INSERT INTO users(id,email,hash,salt,created) VALUES(?,?,?,?,?)').bind(id, email, await hashPw(pw, salt), salt, Date.now()).run();
    return json({uid:id, token: await newSession(env, id)});
  }
  if(route==='/api/login'){
    const email = String(body.email||'').trim().toLowerCase(), pw = String(body.password||'');
    const u = await env.DB.prepare('SELECT id,hash,salt FROM users WHERE email=?').bind(email).first();
    if(!u || !sameStr(await hashPw(pw, u.salt), u.hash)) fail(401,'bad-login','Email or password is wrong.');
    return json({uid:u.id, token: await newSession(env, u.id)});
  }
  const me = await userFrom(req, env);
  if(route==='/api/me') return json({uid:me});
  if(route==='/api/logout'){ await env.DB.prepare('DELETE FROM sessions WHERE token=?').bind((req.headers.get('authorization')||'').slice(7)).run(); return json({ok:true}); }
  if(route==='/api/db'){
    const {op, path} = body;
    if(op==='query'){ checkPath(path, false); if(!(await canRead(env, me, path, body))) denied(); return json({docs: await runQuery(env, path, body.where, body.order, body.limit)}); }
    checkPath(path, true);
    const old = await getDoc(env, path);
    if(op==='get'){ if(!(await canRead(env, me, path))) denied(); return json({data: old}); }
    if(op==='delete'){ if(!old) return json({ok:true}); if(!(await canWrite(env, me, 'delete', path, old, null))) denied(); await delDoc(env, path); return json({ok:true}); }
    if(!isObj(body.data)) fail(400,'invalid','Bad data.');
    let neu;
    if(op==='set') neu = body.data;
    else if(op==='update'){ if(!old) fail(404,'not-found','That no longer exists.'); neu = deepMerge(old, body.data); }
    else if(op==='merge') neu = deepMerge(old, body.data);
    else fail(400,'invalid','Unknown operation.');
    if(!(await canWrite(env, me, old?'update':'create', path, old, neu))) denied();
    await putDoc(env, path, neu);
    if(!old && ctx) ctx.waitUntil(afterCreate(env, me, path, neu).catch(e=>console.error('push', e)));
    return json({ok:true});
  }
  if(route==='/api/media/delete'){ const id=String(body.id||''); const row = await env.DB.prepare('SELECT uid FROM media WHERE id=?').bind(id).first();
    if(row && row.uid===me) await env.DB.batch([env.DB.prepare('DELETE FROM media_parts WHERE id=?').bind(id), env.DB.prepare('DELETE FROM media WHERE id=?').bind(id)]); return json({ok:true}); }
  if(route==='/api/music'){
    const q = String(body.q||'').trim().slice(0,80), cc = (String(body.cc||'au').toLowerCase().match(/^[a-z]{2}$/)||['au'])[0];
    const key = new Request('https://popchat-music.cache/'+cc+'/'+encodeURIComponent(q||'__top'));
    try{ const hit = await caches.default.match(key); if(hit) return hit; }catch(_){}
    let tracks = [], errs = 0;
    try{ tracks = await appleTracks(q, cc); }catch(e){ errs++; console.error('apple music', String(e)); }
    if(!tracks.length){ try{ tracks = await deezerTracks(q); }catch(e){ errs++; console.error('deezer', String(e)); } }
    if(!tracks.length && errs) fail(502,'music','Couldn’t load songs right now. Try again in a moment.');
    const res = new Response(JSON.stringify({tracks}), {headers:{'content-type':'application/json','cache-control':'public, max-age=3600'}});
    try{ if(ctx && tracks.length) ctx.waitUntil(caches.default.put(key, res.clone())); }catch(_){}
    return res;
  }
  if(route==='/api/news'){
    const cat = NEWS[body.cat] ? body.cat : 'top';
    const key = new Request('https://popchat-news.cache/v1/'+cat);
    try{ const hit = await caches.default.match(key); if(hit) return hit; }catch(_){}
    const got = await Promise.allSettled(NEWS[cat].map(async ([src, u]) => parseFeed(await getText(u), src)));
    got.forEach((g,i) => { if(g.status==='rejected') console.error('news', NEWS[cat][i][1], String(g.reason)); });
    const seen = new Set(); const items = got.flatMap(g => g.status==='fulfilled' ? g.value : [])
      .filter(n => { const k = n.title.toLowerCase().replace(/\W+/g,''); if(seen.has(k)) return false; seen.add(k); return true; })
      .sort((a,b) => b.ts - a.ts).slice(0, 45);
    if(!items.length) fail(502,'news','Couldn’t load the news right now. Try again soon.');
    const res = new Response(JSON.stringify({items}), {headers:{'content-type':'application/json','cache-control':'public, max-age=600'}});
    try{ if(ctx) ctx.waitUntil(caches.default.put(key, res.clone())); }catch(_){}
    return res;
  }
  if(route==='/api/vapid'){ const v = await getVapid(env); return json({key: v.pub}); }
  if(route==='/api/push/subscribe'){
    const sub = body.sub||{}; const ep = String(sub.endpoint||''), p = String(sub.keys?.p256dh||''), a = String(sub.keys?.auth||'');
    if(!/^https:\/\//.test(ep) || !p || !a || ep.length>1000) fail(400,'invalid','Bad subscription.');
    await env.DB.prepare('INSERT INTO push_subs(endpoint,uid,p256dh,auth,created) VALUES(?,?,?,?,?) ON CONFLICT(endpoint) DO UPDATE SET uid=excluded.uid, p256dh=excluded.p256dh, auth=excluded.auth').bind(ep, me, p, a, Date.now()).run();
    return json({ok:true});
  }
  if(route==='/api/push/unsubscribe'){ await env.DB.prepare('DELETE FROM push_subs WHERE endpoint=? AND uid=?').bind(String(body.endpoint||''), me).run(); return json({ok:true}); }
  if(route==='/api/push/test'){ const n = await pushTo(env, me, {title:'Popchat', body:'Notifications are working 🎉', url:'/', tag:'test'}, true); return json({sent:n}); }
  if(route==='/api/sync'){
    const reads = Array.isArray(body.reads) ? body.reads.slice(0,80) : [];
    const vers = Object.fromEntries((await env.DB.prepare('SELECT k,v FROM meta').all()).results.map(r=>[r.k, r.v]));
    const results = {}, errors = {};
    await Promise.all(reads.map(async r => {
      try{
        const cv = vers[rootOf(String(r.path))] || 0; if(r.v === cv) return;
        if(r.kind==='query'){ checkPath(r.path, false); if(!(await canRead(env, me, r.path, r))) denied(); results[r.id] = {v:cv, out: await runQuery(env, r.path, r.where, r.order, r.limit)}; }
        else { checkPath(r.path, true); if(!(await canRead(env, me, r.path))) denied(); results[r.id] = {v:cv, out: (await getDoc(env, r.path)) ?? null}; }
      }catch(e){ errors[r.id] = e.code || 'error'; }
    }));
    return json({results, errors});
  }
  fail(404,'not-found','Unknown request.');
}

// ---------- Web Push (VAPID keys are created automatically and kept in the database) ----------
const b64u = buf => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const unb64u = str => { str = str.replace(/-/g,'+').replace(/_/g,'/'); while(str.length%4) str+='='; return Uint8Array.from(atob(str), c=>c.charCodeAt(0)); };
const cat = (...a) => { const out = new Uint8Array(a.reduce((n,x)=>n+x.length,0)); let o=0; for(const x of a){ out.set(x,o); o+=x.length; } return out; };
const enc = new TextEncoder();
let VAPID = null;
async function getVapid(env){
  if(VAPID) return VAPID;
  let row = await env.DB.prepare("SELECT v FROM kv WHERE k='vapid'").first();
  if(!row){
    const kp = await crypto.subtle.generateKey({name:'ECDSA', namedCurve:'P-256'}, true, ['sign','verify']);
    const val = JSON.stringify({pub: b64u(await crypto.subtle.exportKey('raw', kp.publicKey)), jwk: await crypto.subtle.exportKey('jwk', kp.privateKey)});
    await env.DB.prepare("INSERT OR IGNORE INTO kv(k,v) VALUES('vapid',?)").bind(val).run();
    row = await env.DB.prepare("SELECT v FROM kv WHERE k='vapid'").first();
  }
  const v = JSON.parse(row.v);
  VAPID = {pub: v.pub, key: await crypto.subtle.importKey('jwk', v.jwk, {name:'ECDSA', namedCurve:'P-256'}, false, ['sign'])};
  return VAPID;
}
async function vapidAuth(env, endpoint, host){
  const v = await getVapid(env); const aud = new URL(endpoint).origin;
  const head = b64u(enc.encode(JSON.stringify({typ:'JWT', alg:'ES256'})));
  const claims = b64u(enc.encode(JSON.stringify({aud, exp: Math.floor(Date.now()/1000) + 12*3600, sub: 'https://' + host})));
  const sig = await crypto.subtle.sign({name:'ECDSA', hash:'SHA-256'}, v.key, enc.encode(head+'.'+claims));
  return `vapid t=${head}.${claims}.${b64u(sig)}, k=${v.pub}`;
}
async function hkdf(salt, ikm, info, len){ const k = await crypto.subtle.importKey('raw', ikm, 'HKDF', false, ['deriveBits']); return new Uint8Array(await crypto.subtle.deriveBits({name:'HKDF', hash:'SHA-256', salt, info}, k, len*8)); }
async function encryptPush(sub, payload){
  const uaPub = unb64u(sub.p256dh), secret = unb64u(sub.auth);
  const eph = await crypto.subtle.generateKey({name:'ECDH', namedCurve:'P-256'}, true, ['deriveBits']);
  const asPub = new Uint8Array(await crypto.subtle.exportKey('raw', eph.publicKey));
  const uaKey = await crypto.subtle.importKey('raw', uaPub, {name:'ECDH', namedCurve:'P-256'}, false, []);
  const shared = new Uint8Array(await crypto.subtle.deriveBits({name:'ECDH', public: uaKey}, eph.privateKey, 256));
  const ikm = await hkdf(secret, shared, cat(enc.encode('WebPush: info\0'), uaPub, asPub), 32);
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const cek = await hkdf(salt, ikm, enc.encode('Content-Encoding: aes128gcm\0'), 16);
  const nonce = await hkdf(salt, ikm, enc.encode('Content-Encoding: nonce\0'), 12);
  const key = await crypto.subtle.importKey('raw', cek, 'AES-GCM', false, ['encrypt']);
  const ct = new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM', iv: nonce}, key, cat(enc.encode(payload), new Uint8Array([2]))));
  const rs = new Uint8Array([0,0,16,0]);
  return cat(salt, rs, new Uint8Array([asPub.length]), asPub, ct);
}
async function pushTo(env, uid, msg, force){
  if(!force){ const pr = await getDoc(env, 'presence/'+uid); if(pr && pr.online && Date.now() - pr.online < 100000) return 0; }
  const subs = (await env.DB.prepare('SELECT endpoint,p256dh,auth FROM push_subs WHERE uid=?').bind(uid).all()).results;
  const host = PUSH_HOST.value || 'popchat.app'; let sent = 0;
  await Promise.all(subs.map(async sub => {
    try{
      const body = await encryptPush(sub, JSON.stringify(msg));
      const r = await fetch(sub.endpoint, {method:'POST', headers:{'TTL':'86400','Urgency':'high','Content-Encoding':'aes128gcm','Content-Type':'application/octet-stream', 'Authorization': await vapidAuth(env, sub.endpoint, host), ...(msg.tag?{'Topic': msg.tag.replace(/[^A-Za-z0-9_-]/g,'').slice(0,32)}:{})}, body});
      if(r.status===404 || r.status===410) await env.DB.prepare('DELETE FROM push_subs WHERE endpoint=?').bind(sub.endpoint).run();
      else if(r.ok) sent++;
      else console.error('push failed', r.status, await r.text().catch(()=>''));
    }catch(e){ console.error('push error', e); }
  }));
  return sent;
}
const PUSH_HOST = {value:''};
async function afterCreate(env, me, path, doc){
  const s = path.split('/');
  const who = async id => { const p = await getDoc(env, 'profiles/'+id); return p?.username || p?.name || 'Someone'; };
  if(s.length===4 && s[0]==='chats' && s[2]==='msgs'){
    const chat = await getDoc(env, 'chats/'+s[1]); if(!chat || doc.type==='sys') return;
    const name = chat.nick?.[me] || await who(me);
    const body = doc.type==='photo' ? 'Sent a photo 📷' : doc.type==='snap' ? 'Sent a snap 👀' : doc.type==='voice' ? 'Sent a voice message 🎤' : doc.type==='post' ? 'Shared a post' : doc.type==='news' ? 'Shared a news story 📰' : doc.type==='comm' ? 'Invited you to a community' : doc.type==='sticker' ? doc.s : (doc.story ? 'Replied to your story: ' : '') + String(doc.text||'').slice(0,140);
    const title = chat.type==='group' ? `${name} · ${chat.name||'Group'}` : name;
    await Promise.all((chat.members||[]).filter(u=>u!==me && !chat.mute?.[u]).map(u => pushTo(env, u, {title, body, url:'/#chats', tag:'chat-'+s[1]})));
  } else if(s.length===2 && s[0]==='stories'){
    // stories reset daily: tidy up this person's stories from before yesterday
    const old = await env.DB.prepare("SELECT path, data FROM docs WHERE coll='stories' AND json_extract(data,'$.by')=? AND json_extract(data,'$.ts')<? LIMIT 50").bind(me, Date.now()-2*86400000).all();
    for(const r of old.results){ let m = {}; try{ m = JSON.parse(r.data).media || {}; if(typeof m==='string') m = JSON.parse(m); }catch(_){}
      if(m?.imgRef) await delDoc(env, 'images/'+m.imgRef);
      if(m?.vid) await env.DB.batch([env.DB.prepare('DELETE FROM media_parts WHERE id=?').bind(m.vid), env.DB.prepare('DELETE FROM media WHERE id=?').bind(m.vid)]);
      await delDoc(env, r.path); }
  } else if(s.length===4 && s[0]==='notifs' && s[2]==='items' && s[1]!==me){
    const name = await who(me);
    const t = {like:'liked your post ❤️', comment:'commented: ' + String(doc.text||'').slice(0,100), mention:'mentioned you: ' + String(doc.text||'').slice(0,100), tag: doc.story ? 'tagged you in their story' : 'tagged you in a post', freq:'sent you a friend request 👋', fok:'accepted your friend request 🎉', creply:'answered your question: ' + String(doc.text||'').slice(0,100)}[doc.type];
    if(t) await pushTo(env, s[1], {title:'Popchat', body:`${name} ${t}`, url: doc.type==='freq'||doc.type==='fok' ? '/' : '/#activity', tag: doc.type==='like' ? 'likes' : undefined});
  }
}

// ---------- news (headlines from public RSS feeds; stories open on the publisher's site) ----------
const NEWS = {
  top:[['ABC News','https://www.abc.net.au/news/feed/10719986/rss.xml'],['The Guardian','https://www.theguardian.com/au/rss'],['BBC News','https://feeds.bbci.co.uk/news/rss.xml']],
  australia:[['ABC News','https://www.abc.net.au/news/feed/10719976/rss.xml'],['ABC News WA','https://www.abc.net.au/news/feed/5313390/rss.xml'],['The Guardian','https://www.theguardian.com/australia-news/rss']],
  world:[['ABC News','https://www.abc.net.au/news/feed/104217382/rss.xml'],['BBC News','https://feeds.bbci.co.uk/news/world/rss.xml'],['The Guardian','https://www.theguardian.com/world/rss']],
  tech:[['BBC News','https://feeds.bbci.co.uk/news/technology/rss.xml'],['The Guardian','https://www.theguardian.com/technology/rss'],['The Verge','https://www.theverge.com/rss/index.xml']],
  sport:[['ABC Sport','https://www.abc.net.au/news/feed/103728570/rss.xml'],['BBC Sport','https://feeds.bbci.co.uk/sport/rss.xml'],['The Guardian','https://www.theguardian.com/au/sport/rss']],
  culture:[['ABC News','https://www.abc.net.au/news/feed/103728568/rss.xml'],['BBC News','https://feeds.bbci.co.uk/news/entertainment_and_arts/rss.xml'],['The Guardian','https://www.theguardian.com/au/culture/rss']],
};
async function getText(u){ const r = await fetch(u, {headers:{...UA, accept:'application/rss+xml, application/atom+xml, application/xml, text/xml, */*'}, signal:AbortSignal.timeout(6000)}); if(!r.ok) throw new Error('HTTP '+r.status); return await r.text(); }
const ENT = {amp:'&', lt:'<', gt:'>', quot:'"', apos:"'", nbsp:' ', hellip:'…', mdash:'—', ndash:'–', lsquo:'‘', rsquo:'’', ldquo:'“', rdquo:'”'};
const unent = s => String(s||'').replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m,e) => e[0]==='#' ? (()=>{ try{ return String.fromCodePoint(e[1].toLowerCase()==='x' ? parseInt(e.slice(2),16) : +e.slice(1)); }catch(_){ return ''; } })() : (ENT[e.toLowerCase()] ?? m));
const cdata = s => String(s||'').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1');
const textOf = s => unent(unent(cdata(s)).replace(/<[^>]*>/g, ' ')).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const xtag = (x, n) => { const m = x.match(new RegExp('<'+n+'(?:\\s[^>]*)?>([\\s\\S]*?)</'+n+'>', 'i')); return m ? m[1] : ''; };
function parseFeed(xml, source){
  const items = xml.match(/<item[\s>][\s\S]*?<\/item>/gi) || xml.match(/<entry[\s>][\s\S]*?<\/entry>/gi) || [];
  return items.slice(0, 25).map(it => {
    const title = textOf(xtag(it,'title')).slice(0, 220);
    let link = textOf(xtag(it,'link')); if(!/^https?:\/\//.test(link)){ const m = it.match(/<link[^>]*rel="alternate"[^>]*href="([^"]+)"/i) || it.match(/<link[^>]*href="([^"]+)"/i); link = m ? unent(m[1]) : ''; }
    if(!/^https?:\/\//.test(link)){ const g = textOf(xtag(it,'guid')); if(/^https?:\/\//.test(g)) link = g; }
    link = link.replace(/^http:\/\//, 'https://');
    const ts = Date.parse(textOf(xtag(it,'pubDate') || xtag(it,'dc:date') || xtag(it,'published') || xtag(it,'updated'))) || 0;
    const desc = textOf(xtag(it,'description') || xtag(it,'summary')).slice(0, 260);
    const cands = [];
    for(const m of it.matchAll(/<(media:content|media:thumbnail|enclosure)\b([^>]*)>/gi)){ const a = m[2]; const u = (a.match(/url="([^"]+)"/i)||[])[1]; if(!u) continue;
      const ty = (a.match(/type="([^"]+)"/i)||[])[1] || ''; if(ty && !ty.startsWith('image')) continue; if(/medium="(video|audio)"/i.test(a)) continue;
      cands.push([+((a.match(/width="(\d+)"/i)||[])[1] || 0), unent(u)]); }
    let img = ''; if(cands.length){ const ok = cands.filter(c=>c[0] && c[0]<=1100).sort((a,b)=>b[0]-a[0]); img = (ok[0] || cands.sort((a,b)=>a[0]-b[0]).find(c=>c[0]) || cands[0])[1]; }
    if(!img){ const raw = unent(cdata(xtag(it,'content:encoded') || xtag(it,'content') || xtag(it,'description'))); const m = raw.match(/<img[^>]+src="([^"]+)"/i); if(m) img = unent(m[1]); }
    img = img.replace(/^http:\/\//, 'https://').replace(/\/(standard|news)\/(\d{2,3})\//, '/$1/800/');
    return {title, link, ts, desc, img: /^https:\/\//.test(img) ? img : '', source};
  }).filter(n => n.title && /^https:\/\//.test(n.link));
}

// ---------- music sources ----------
const UA = {'user-agent':'Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1', 'accept':'application/json'};
async function getJSON(u){ const r = await fetch(u, {headers:UA, signal:AbortSignal.timeout(5000)}); if(!r.ok) throw new Error('HTTP '+r.status+' '+u); return JSON.parse(await r.text()); }
async function appleTracks(q, cc){
  let list = [];
  if(q) list = (await getJSON(`https://itunes.apple.com/search?term=${encodeURIComponent(q)}&media=music&entity=song&limit=25&country=${cc}`)).results || [];
  else { const ids = ((await getJSON(`https://rss.applemarketingtools.com/api/v2/${cc}/music/most-played/40/songs.json`)).feed?.results||[]).map(x=>x.id).filter(Boolean).slice(0,40).join(',');
    if(ids) list = (await getJSON(`https://itunes.apple.com/lookup?id=${ids}&country=${cc}`)).results || []; }
  return list.filter(t => t.previewUrl && (t.kind==='song' || t.wrapperType==='track')).map(t => ({id:String(t.trackId), title:t.trackName, artist:t.artistName, art:String(t.artworkUrl100||'').replace(/\d+x\d+bb/,'300x300bb'), preview:t.previewUrl, url:t.trackViewUrl, explicit:t.trackExplicitness==='explicit'}));
}
async function deezerTracks(q){
  const d = await getJSON(q ? `https://api.deezer.com/search?q=${encodeURIComponent(q)}&limit=25` : 'https://api.deezer.com/chart/0/tracks?limit=40');
  if(d.error) throw new Error('deezer '+JSON.stringify(d.error));
  return (d.data||d.tracks?.data||[]).filter(t => t.preview && t.id).map(t => ({id:'dz'+t.id, src:'dz', title:t.title_short||t.title, artist:t.artist?.name||'', art:t.album?.cover_medium||t.album?.cover||'', preview:'/music/p/dz/'+t.id, url:t.link||('https://www.deezer.com/track/'+t.id), explicit:!!t.explicit_lyrics}));
}
// Deezer preview links expire, so posts store /music/p/dz/{id} and we look up a fresh link when it plays.
async function musicPreview(id, ctx){
  if(!/^\d{1,15}$/.test(id)) return new Response('Not found', {status:404});
  const key = new Request('https://popchat-music.cache/dzp/'+id);
  try{ const hit = await caches.default.match(key); if(hit) return hit; }catch(_){}
  let t; try{ t = await getJSON('https://api.deezer.com/track/'+id); }catch(e){ return new Response('Song unavailable', {status:502}); }
  if(!t?.preview) return new Response('Song unavailable', {status:404});
  const res = new Response(null, {status:302, headers:{location:t.preview, 'cache-control':'public, max-age=600'}});
  try{ ctx.waitUntil(caches.default.put(key, res.clone())); }catch(_){}
  return res;
}

// ---------- video storage (split into small pieces in D1) ----------
const CHUNK = 262144, MAX_PARTS = 160;
const MEDIA_ID = /^[a-z0-9]{16,40}$/;
async function mediaPart(req, env){
  const me = await userFrom(req, env); const q = new URL(req.url).searchParams;
  const id = q.get('id')||'', part = +q.get('part'), parts = +q.get('parts'), size = +q.get('size'), type = (q.get('type')||'').split(';')[0];
  if(!MEDIA_ID.test(id) || !Number.isInteger(part) || !Number.isInteger(parts) || parts<1 || parts>MAX_PARTS || part<0 || part>=parts || !(size>0) || size>parts*CHUNK || !/^video\/(mp4|webm|quicktime|x-m4v)$/.test(type)) fail(400,'invalid','That video can’t be uploaded.');
  const row = await env.DB.prepare('SELECT uid,parts,done FROM media WHERE id=?').bind(id).first();
  if(row && (row.uid!==me || row.parts!==parts || row.done)) fail(403,'permission-denied','That upload isn’t yours.');
  const data = new Uint8Array(await req.arrayBuffer());
  if(!data.length || data.length > CHUNK || (part<parts-1 && data.length!==CHUNK)) fail(400,'invalid','Upload piece is the wrong size.');
  const stmts = [];
  if(!row) stmts.push(env.DB.prepare('INSERT OR IGNORE INTO media(id,uid,type,size,parts,done,created) VALUES(?,?,?,?,?,0,?)').bind(id, me, type, size, parts, Date.now()));
  stmts.push(env.DB.prepare('INSERT OR REPLACE INTO media_parts(id,part,data) VALUES(?,?,?)').bind(id, part, data));
  await env.DB.batch(stmts);
  const c = await env.DB.prepare('SELECT COUNT(*) AS n FROM media_parts WHERE id=?').bind(id).first();
  if(c.n===parts) await env.DB.prepare('UPDATE media SET done=1 WHERE id=?').bind(id).run();
  return json({ok:true, done: c.n===parts});
}
async function serveMedia(req, env, id){
  if(!MEDIA_ID.test(id)) return new Response('Not found', {status:404});
  const meta = await env.DB.prepare('SELECT type,size,parts,done FROM media WHERE id=?').bind(id).first();
  if(!meta || !meta.done) return new Response('Not found', {status:404});
  const size = meta.size; const base = {'content-type':meta.type, 'accept-ranges':'bytes', 'cache-control':'public, max-age=31536000, immutable'};
  const range = req.headers.get('range'); let start = 0, end = size-1, partial = false;
  if(range){ const m = /^bytes=(\d*)-(\d*)$/.exec(range.trim());
    if(m){ partial = true; if(m[1]===''){ start = Math.max(0, size - (+m[2]||0)); } else { start = +m[1]; if(m[2]!=='') end = Math.min(+m[2], size-1); } } }
  if(start >= size || start > end) return new Response(null, {status:416, headers:{...base, 'content-range':`bytes */${size}`}});
  const toBytes = d => d instanceof ArrayBuffer ? new Uint8Array(d) : new Uint8Array(d);
  if(partial){
    end = Math.min(end, start + 4*CHUNK - 1);
    const pa = Math.floor(start/CHUNK), pb = Math.floor(end/CHUNK);
    const rows = (await env.DB.prepare('SELECT part,data FROM media_parts WHERE id=? AND part BETWEEN ? AND ? ORDER BY part').bind(id, pa, pb).all()).results;
    const out = new Uint8Array(end-start+1); let o = 0;
    for(const r of rows){ const b = toBytes(r.data); const ps = r.part*CHUNK; const s0 = Math.max(start, ps) - ps, s1 = Math.min(end+1, ps+b.length) - ps; if(s1>s0){ out.set(b.subarray(s0, s1), o); o += s1-s0; } }
    return new Response(out, {status:206, headers:{...base, 'content-length':String(out.length), 'content-range':`bytes ${start}-${end}/${size}`}});
  }
  let p = 0;
  const stream = new ReadableStream({ async pull(ctrl){
    if(p >= meta.parts){ ctrl.close(); return; }
    const r = await env.DB.prepare('SELECT data FROM media_parts WHERE id=? AND part=?').bind(id, p++).first();
    if(!r){ ctrl.error(new Error('missing')); return; } ctrl.enqueue(toBytes(r.data)); } });
  return new Response(stream, {status:200, headers:{...base, 'content-length':String(size)}});
}

const ICONS = {"icon-192.png": "", "icon-512.png": "", "apple-touch-icon.png": "", "favicon-64.png": ""};
const MANIFEST = JSON.stringify({
  name:'Popchat', short_name:'Popchat', description:'Photos, stories and snaps with your friends.',
  start_url:'/', scope:'/', display:'standalone', orientation:'portrait', background_color:'#000000', theme_color:'#000000',
  icons:[{src:'/icon-192.png',sizes:'192x192',type:'image/png',purpose:'any'},{src:'/icon-512.png',sizes:'512x512',type:'image/png',purpose:'any'},{src:'/icon-512.png',sizes:'512x512',type:'image/png',purpose:'maskable'}]
});
const SW = `self.addEventListener('install', function(e){ self.skipWaiting(); });
self.addEventListener('activate', function(e){ e.waitUntil(self.clients.claim()); });
self.addEventListener('fetch', function(e){ if(e.request.mode==='navigate') e.respondWith(fetch(e.request).catch(function(){ return new Response('<h1 style="font-family:sans-serif;text-align:center;margin-top:30vh">You are offline</h1><p style="font-family:sans-serif;text-align:center">Popchat needs the internet. Reconnect and try again.</p>',{headers:{'content-type':'text/html'}}); })); });
self.addEventListener('push', function(e){
  var d = {}; try{ d = e.data ? e.data.json() : {}; }catch(_){ d = {body: e.data ? e.data.text() : ''}; }
  e.waitUntil(self.registration.showNotification(d.title || 'Popchat', {body: d.body || '', icon: '/icon-192.png', badge: '/icon-192.png', tag: d.tag || undefined, renotify: !!d.tag, data: {url: d.url || '/'}}));
});
self.addEventListener('notificationclick', function(e){
  e.notification.close(); var url = (e.notification.data && e.notification.data.url) || '/';
  e.waitUntil(self.clients.matchAll({type:'window', includeUncontrolled:true}).then(function(cs){
    for(var i=0;i<cs.length;i++){ var c=cs[i]; if('focus' in c){ c.postMessage({type:'open', url:url}); return c.focus(); } }
    return self.clients.openWindow(url);
  }));
});`;
function staticAsset(path){
  const name = path === '/favicon.ico' ? 'favicon-64.png' : path.slice(1);
  if(ICONS[name]){ const bin = Uint8Array.from(atob(ICONS[name]), c=>c.charCodeAt(0)); return new Response(bin, {headers:{'content-type':'image/png','cache-control':'public, max-age=86400'}}); }
  if(path==='/manifest.webmanifest') return new Response(MANIFEST, {headers:{'content-type':'application/manifest+json','cache-control':'public, max-age=3600'}});
  if(path==='/sw.js') return new Response(SW, {headers:{'content-type':'text/javascript','cache-control':'no-cache'}});
  return null;
}

export default {
  async fetch(req, env, ctx){
    const url = new URL(req.url); PUSH_HOST.value = url.host;
    const asset = staticAsset(url.pathname); if(asset) return asset;
    if(!env.DB) return new Response(SETUP_HTML, {status: url.pathname.startsWith('/api/') ? 503 : 200, headers:{'content-type':'text/html;charset=utf-8'}});
    try{
      await ensureSchema(env);
      if(url.pathname.startsWith('/music/p/dz/')) return await musicPreview(url.pathname.slice(12), ctx);
      if(url.pathname.startsWith('/media/')) return await serveMedia(req, env, url.pathname.slice(7));
      if(url.pathname==='/api/media/part'){ if(req.method!=='POST') return json({code:'method', msg:'Use POST.'}, 405); return await mediaPart(req, env); }
      if(url.pathname.startsWith('/api/')){
        if(req.method!=='POST') return json({code:'method', msg:'Use POST.'}, 405);
        return await api(req, env, url.pathname, ctx);
      }
      return new Response(APP_HTML, {headers:{'content-type':'text/html;charset=utf-8','cache-control':'no-cache','x-content-type-options':'nosniff','referrer-policy':'same-origin'}});
    }catch(e){
      if(e instanceof HttpError) return json({code:e.code, msg:e.msg}, e.status);
      console.error(e); return json({code:'server', msg:'Popchat had a problem on the server. Try again.'}, 500);
    }
  }
};
